import java.util.Scanner;

public class Main {
    public static void solve() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();
        int m = n * (n - 1) / 2;
        int max_x = n * (n - 1);
        int[][] dp = new int[n + 1][max_x + 1];
        int[][] dp1 = new int[n + 1][max_x + 1];

        dp[1][m] = 1;

        for (int i = 2; i <= n; i++) {
            int start_x = m - (i - 1) * (i - 2) / 2;
            int end_x = m + (i - 1) * (i - 2) / 2;
            for (int x = start_x; x <= end_x; x++) {
                for (int d = -i + 1; d < i; d++) {
                    int x_d = x + d;
                    if (0 <= x_d && x_d <= max_x) {
                        dp[i][x_d] = (dp[i][x_d] + (int)((long)dp[i - 1][x] * (i - Math.abs(d)) % mod)) % mod;
                    }
                }
            }
        }

        for (int i = 2; i <= n; i++) {
            int start_x = m - (i - 1) * (i - 2) / 2;
            int end_x = m + (i - 1) * (i - 2) / 2;
            for (int x = start_x; x <= end_x; x++) {
                dp1[i][x] = (int)((long)dp1[i - 1][x] * i % mod);
            }
            for (int x = start_x; x <= end_x; x++) {
                for (int d = 1; d < i; d++) {
                    int x_d = x - d;
                    if (0 <= x_d && x_d <= max_x) {
                        dp1[i][x_d] = (int)((dp1[i][x_d] + (long)dp[i - 1][x] * (i - d) % mod) % mod);
                    }
                }
            }
        }

        long sum = 0;
        for (int x = m + 1; x <= max_x; x++) {
            sum = (sum + dp1[n][x]) % mod;
        }
        System.out.println(sum);
        sc.close();
    }

    public static void main(String[] args) {
        solve();
    }
}
